function tripDestinations(): array {static $resolved=[];$destinationLanguage=siteLanguage();if(isset($resolved[$destinationLanguage]))return $resolved[$destinationLanguage];$destinationArticles=experienceArticles();$destinations=array_merge([
 'Tbilisi'=>['slug'=>'tbilisi','country'=>'georgia','labels'=>['טביליסי','Tbilisi','Тбилиси'],'country_labels'=>['גאורגיה','Georgia','Грузия'],'image'=>'tbilisi-metekhi.jpg','credit'=>'Holger Zacharias · Public domain'],
 'Prague'=>['slug'=>'prague','country'=>'czechia','labels'=>['פראג','Prague','Прага'],'country_labels'=>['צ׳כיה','Czechia','Чехия'],'image'=>'prague.jpg','credit'=>'Slyronit · CC BY-SA 4.0'],
 'Budapest'=>['slug'=>'budapest','country'=>'hungary','labels'=>['בודפשט','Budapest','Будапешт'],'country_labels'=>['הונגריה','Hungary','Венгрия'],'image'=>'guides/03-hero.webp','credit'=>''],
 ],array_combine(array_keys(activityDestinations()),array_map(function($name,$labels)use($destinationArticles){$photo=['Las Vegas'=>'us-grand-canyon-helicopter','New York'=>'us-new-york-helicopter','San Francisco'=>'us-san-francisco-bay-cruise','Miami'=>'us-miami-biscayne-bay-cruise','New Orleans'=>'us-new-orleans-food-tour','Hawaii'=>'us-oahu-circle-island'];$rows=experienceCatalog();$match=array_values(array_filter($rows,fn($r)=>$r['region']===$name));$im=$match[0]['images'][0]??[];return ['slug'=>strtolower(str_replace(' ','-',$name)),'country'=>'united-states','labels'=>$labels,'country_labels'=>['ארצות הברית','United States','США'],'image'=>isset($match[0])?imageFor($destinationArticles[array_search($match[0]['id'],array_column($destinationArticles,'id'))]):'prague.jpg','credit'=>($im['author']??'').' · '.($im['license']??'')];},array_keys(activityDestinations()),array_values(activityDestinations()))));
 foreach(editorialDocuments() as $id=>$doc){if($doc['record_type']!=='destination'||strpos($id,'dest-')===0||($doc['editorial']['destination_kind']??'')!=='city')continue;$ed=$doc['editorial'];$tr=$ed['translations'];if(empty($tr[siteLanguage()]['title'])&&empty($tr['en']['title']))continue;$parent=editorialDocuments()[$ed['parent_destination_id']??'']['editorial']['translations']??[];$media=editorialMedia($ed);if(!$media)foreach(editorialDocuments() as $place){if(in_array($id,$place['editorial']['destination_ids']??[],true)){$media=editorialMedia($place['editorial']);if($media)break;}}$iso=$ed['country_code']??$id;$country=['GE'=>'georgia','CZ'=>'czechia','HU'=>'hungary','US'=>'united-states'][$iso]??strtolower($iso);$destinations[$id]=['slug'=>$id,'country'=>$country,'country_code'=>$iso,'labels'=>[$tr['he']['title']??'',$tr['en']['title']??'',$tr['ru']['title']??''],'country_labels'=>[$parent['he']['title']??$iso,$parent['en']['title']??$iso,$parent['ru']['title']??$iso],'image'=>isset($media['image'])?substr($media['image'],8):'','credit'=>$media['credit']??''];}return $resolved[$destinationLanguage]=array_replace(providerCatalogDestinations($destinations),json_decode(file_get_contents(ROOT.'/content/community-destinations.json'),true));}

function tripCurrency(): string {$default=tripDefaultCurrency(siteLanguage());$c=$_GET['currency']??((($_GET['switch_lang']??'')==='1')?null:($_COOKIE['tripovela_currency_'.siteLanguage()]??null))??$default;return is_string($c)&&isset(tripCurrencies()[$c])?$c:$default;}
function tripCatalogDb(): ?PDO {static $d;if($d)return $d;$f=STORAGE_PATH.'/catalog.sqlite';if(!is_file($f))return null;$d=new PDO('sqlite:'.$f);$d->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$d->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);$d->exec('PRAGMA busy_timeout=5000');return $d;}
function tripCatalog(): array {
 static $cached=[];$cacheKey=siteLanguage()."|".tripCurrency();if(isset($cached[$cacheKey]))return $cached[$cacheKey];
 $items=[];$ru=json_decode(file_get_contents(ROOT.'/content/planner-ru.json'),true);
 foreach(experienceArticles() as $a){$m=$a['_meta'];$code=$m['product_code'];$im=$m['images'][0];$d=activityMetadata()[$code]['duration']??[];$items[]=['id'=>$a['id'],'city'=>$m['region'],'title'=>siteLanguage()==='ru'?($ru[$a['id']]??activityTitle($a)):activityTitle($a),'summary'=>$m['languages'][siteLanguage()==='he'?'he':'en']['best_for'],'type'=>activityMetadata()[$code]['type']??'city','duration'=>activityDuration($code),'minutes'=>$d['fixedDurationInMinutes']??$d['variableDurationFromMinutes']??null,'image'=>'/assets/'.imageFor($a),'credit'=>($im['author']??'').' · '.($im['license']??''),'image_disclosure'=>['photo_author'=>$im['author']??'','photo_source'=>$im['commons_page']??'','photo_license'=>($im['license']??'').' '.($im['license_url']??'')],'url'=>languageUrl('/guides/'.$a['slug'].'/',siteLanguage()),'cost'=>'paid','product'=>$code];}
 $extra=json_decode(file_get_contents(ROOT.'/content/places.json'),true);
 foreach($extra as $r){$replacement=['charles-bridge'=>'free50-free-015-charles-bridge','rike-park'=>'free50-free-027-rike-park'][$r['id']]??null;if($replacement&&isset(editorialDocuments()[$replacement]))continue;$r['title']=languagePhrase(...$r['titles']);$r['summary']=languagePhrase(...$r['summaries']);$r['duration']=isset($r['minutes'])?$r['minutes'].' '.languagePhrase('דקות · אומדן תכנון','min · planning estimate','мин · ориентир'):languagePhrase('בקצב שלכם','At your own pace','В своём темпе');$r['url']=languageUrl('/places/'.$r['id'].'/',siteLanguage());unset($r['titles'],$r['summaries']);$items[]=$r;}
 foreach(['Tbilisi'=>['75503P11','05','סיור היכרות עם טביליסי','Tbilisi walking tour','Пешеходная экскурсия по Тбилиси'],'Prague'=>['9396P5','04','סיור בעיר העתיקה ובמצודת פראג','Prague Old Town and Castle walk','Прогулка по старому городу и Пражскому Граду'],'Budapest'=>['35015P2','03','שיט יום בדנובה','Daytime Danube cruise','Дневной круиз по Дунаю']] as $city=>$r){$dest=tripDestinations()[$city];$details=json_decode(file_get_contents(ROOT.'/content/activity-details.json'),true)[$r[0]]??null;if(!$details)continue;$minutes=$details['duration']['fixedDurationInMinutes']??$details['duration']['variableDurationFromMinutes']??null;$items[]=['id'=>'offer-'.strtolower($r[0]),'city'=>$city,'title'=>languagePhrase($r[2],$r[3],$r[4]),'summary'=>languagePhrase('בדקו את מסלול החוויה, נקודת המפגש ושפות ההדרכה.','See this experience’s route, meeting point and guiding languages.','Посмотрите маршрут, место встречи и языки экскурсии.'),'type'=>$city==='Budapest'?'water':'city','duration'=>$minutes?($minutes.' '.languagePhrase('דקות','minutes','минут')):'','minutes'=>$minutes,'image'=>$details['image'],'credit'=>'Viator · '.languagePhrase('תמונת הספק','Supplier image','Фото поставщика'),'url'=>languageUrl('/activities/'.$r[0].'/',siteLanguage()),'cost'=>'paid','product'=>$r[0],'editorial_article'=>$r[1]];}
 $items=array_merge($items,editorialExtraItems(tripDestinations()),providerCatalogItems(tripDestinations()),socialCatalog());
 $db=tripCatalogDb();$overrides=[];if($db){try{foreach($db->query('SELECT id,published FROM editorial_records') as $row)$overrides[$row['id']]=$row['published']?json_decode($row['published'],true):null;}catch(Throwable $e){}}
 foreach($items as &$x){$x['price']=null;$x['price_amount']=null;$x['currency']=tripCurrency();if(!empty($x['product'])){$file=STORAGE_PATH.'/viator-live/weekly-price-'.$x['product'].'.json';$price=is_file($file)?json_decode(file_get_contents($file),true):null;if(($price['status']??'')==='ok'&&($price['expires_at']??0)>time()&&($converted=tripCachedConversion($price,$x['currency']))){$x['price_amount']=$converted['amount'];$x['price']=(!empty($converted['fx_source'])?'≈ ':'').number_format((float)$x['price_amount'],2).' '.($x['currency']==='ILS'?'₪':$x['currency']);$x['price_updated']=gmdate('Y-m-d H:i',is_numeric($price['checked_at']??null)?(int)$price['checked_at']:(($price['expires_at']??time())-604800)).' UTC';}}
  $doc=$overrides['item-'.$x['id']]['editorial']??null;if($doc){$tr=$doc['translations'][siteLanguage()]??null;if($tr){$x['title']=$tr['title']??$x['title'];$x['summary']=$tr['summary']??$x['summary'];}}
  $x=discoveryClassify($x);
 }unset($x);return $cached[$cacheKey]=array_values(array_filter($items,function($x)use($overrides){return catalogLanguageAvailable($x)&&(empty($x['product'])||!catalogProductInactive($x['product']))&&(!array_key_exists('item-'.$x['id'],$overrides)||$overrides['item-'.$x['id']]!==null);}));
}
function tripSaveButton(array $x): string {return '<button type="button" class="button trip-save" data-trip-item="'.e(json_encode($x,JSON_UNESCAPED_UNICODE)).'">♡ '.e(languagePhrase('הוספה לטיול','Add to my trip','В мой план')).'</button>';}
function tripCard(array $x): void { ?><article class="trip-card" translate="no"><a class="trip-card-image" href="<?=e($x['url'])?>"><?php if($x['image']):?><img src="<?=e($x['image'])?>" width="600" height="450" loading="lazy" alt="<?=e($x['title'])?>"><?php else:?><span class="image-fallback">◇</span><?php endif?></a><div class="trip-card-body"><span class="trip-meta"><?=e(activityLabel(tripDestinations()[$x['city']]['labels']))?> · <?=e($x['duration']?:languagePhrase('משך לפי אפשרות','Duration varies','Длительность зависит от варианта'))?></span><h3><a href="<?=e($x['url'])?>"><?=e($x['title'])?></a></h3><p><?=e($x['summary'])?></p><strong class="trip-cost"><?=e($x['price_label']??($x['cost']==='free'?languagePhrase('חינם · ביקור עצמאי','Free · independent visit','Бесплатно · самостоятельно'):($x['price']?languagePhrase('החל מ־','From ','От ').$x['price'].' · '.languagePhrase('לאדם','per person','на человека'):languagePhrase('מחיר וזמינות אצל הספק','Price & availability with provider','Цена и наличие у поставщика'))))?></strong><?=tripSaveButton($x)?><a class="trip-detail" href="<?=e($x['url'])?>"><?=e(languagePhrase('לפרטים','View details','Подробнее'))?> ←</a><small><?=e($x['credit'])?></small></div></article><?php }
function tripDestinationSearch(string $value=''): void { ?><form class="destination-search" action="/plan/" data-destination-search data-rows="<?=e(json_encode(networkDestinationRows(),JSON_UNESCAPED_UNICODE))?>" data-destinations="<?=e(json_encode(tripDestinations(),JSON_UNESCAPED_UNICODE))?>" translate="no"><input type="hidden" name="lang" value="<?=e(siteLanguage())?>"><label class="sr-only" for="destination-search"><?=e(languagePhrase('עיר, אזור או מדינה','City, region or country','Город, регион или страна'))?></label><input id="destination-search" name="q"  required autocomplete="off" value="<?=e($value)?>" placeholder="<?=e(languagePhrase('עיר, אזור או מדינה','City, region or country','Город, регион или страна'))?>"><datalist id="destination-options"><?php foreach(tripDestinations() as $d):?><option value="<?=e(activityLabel($d['labels']))?>" label="<?=e(activityLabel($d['country_labels']).' — '.languagePhrase('עיר','City','Город'))?>"><?php endforeach; $seen=[];foreach(tripDestinations() as $d):if(isset($seen[$d['country']]))continue;$seen[$d['country']]=true;?><option value="<?=e(activityLabel($d['country_labels']))?>" label="<?=e(languagePhrase('מדינה','Country','Страна'))?>"><?php endforeach?></datalist><button class="button"><?=e(languagePhrase('מצאו מה לעשות','Find things to do','Найти идеи для поездки'))?> ←</button></form><?php }

function catalogProductInactive(string $code): bool {
 $state=viatorProductState($code);$db=tripCatalogDb();if(!$db)return ($state['status']??'')==='INACTIVE';try{$q=$db->prepare("SELECT payload,updated_at FROM provider_records WHERE stream='products' AND id=?");$q->execute([$code]);$record=$q->fetch();if(!$record||($state['checked_at']??0)>=(int)$record['updated_at'])return ($state['status']??'')==='INACTIVE';$p=json_decode($record['payload'],true);return ($p['status']??'')==='INACTIVE';}catch(Throwable $e){return ($state['status']??'')==='INACTIVE';}
}

function tripGuidePlan(array $article): void {
 $city=$article['_meta']['region']??null;foreach(tripCatalog() as $x)if(($x['editorial_article']??'')===($article['id']??''))$city=$x['city'];
 if(!$city)return;$places=array_values(array_filter(tripCatalog(),fn($x)=>$x['city']===$city&&$x['cost']==='free'));if(!$places)return;
 ?><details class="guide-plan" translate="no"><summary><?=e(languagePhrase('מקומות שאפשר לשלב — תצוגה לפני הוספה לטיול','Places to include — preview before adding to your trip','Места для поездки — просмотр перед добавлением'))?></summary><p><?=e(languagePhrase('הצעה גמישה לשילוב מקומות, ולא הזמנה או העתקה של מסלול מלא. בחרו את המקומות ואת הימים; פריטים שכבר נשמרו לא יתווספו שוב.','A flexible place plan, not a booking or a copy of the full itinerary. Choose places and days; already saved items will not be duplicated.','Гибкий план мест, не бронирование и не копия полного маршрута. Выберите места и дни; сохранённые места не дублируются.'))?></p><form data-guide-plan data-city="<?=e($city)?>"><?php foreach($places as $i=>$x):?><div class="guide-plan-row"><label><input type="checkbox" name="place" value="<?=e($x['id'])?>" data-title="<?=e($x['title'])?>" checked> <?=e($x['title'])?></label><label><?=e(languagePhrase('יום','Day','День'))?><select name="day-<?=e($x['id'])?>"><?php for($d=1;$d<=3;$d++):?><option value="<?=$d?>" <?=$d===min(3,1+(int)floor($i/2))?'selected':''?>><?=$d?></option><?php endfor?></select></label><a href="<?=e($x['url'])?>"><?=e(languagePhrase('פרטים','Details','Подробнее'))?></a></div><?php endforeach?><button class="button secondary" type="submit"><?=e(languagePhrase('הוספת המקומות הנבחרים לטיול','Add selected places to my trip','Добавить выбранные места в план'))?></button><p class="bundle-status" role="status"></p></form></details><?php
}
